export function getJobGuideEntry(a2Row) {
  if (!a2Row || !a2Row.A) {
    return null;
  }
  const code = String(a2Row.A).trim();
  const normalizedCode = code.replace(/^[A-Z0-9_]+-SN-A1-/, "XXX-SN-A1-");

  if (JOB_GUIDES_BY_CODE[code]) {
    return JOB_GUIDES_BY_CODE[code];
  }
  if (JOB_GUIDES_BY_CODE[normalizedCode]) {
    return JOB_GUIDES_BY_CODE[normalizedCode];
  }

  const jobName = String(a2Row.D || "");
  const product = String(a2Row.E || "sản phẩm hoàn thành");
  const unit = String(a2Row.F || "sản phẩm");

  return {
    C: 24,
    D: 240,
    E: 12,
    howToCountC: `Đếm tổng số "${unit}" đối với công việc "${jobName}" (tương ứng với số lượng "${product}" đã thực hiện hoàn thành trong kỳ 01/10/2025–30/9/2026 lưu tại đơn vị).`,
    howToEstimateD: `Tính tổng số phút thực tế để hoàn thành 01 ${unit} (${product}) đảm bảo yêu cầu "${a2Row.G || "đúng quy định chuyên môn"}" từ bước chuẩn bị, thực hiện đến khi hoàn tất hồ sơ.`,
    howToEstimateE: `Số giờ phát sinh thêm trong năm cho công tác họp phối hợp, rà soát, chỉnh sửa liên quan đến "${jobName}" (Gợi ý: 12 giờ/năm; nếu không phát sinh thì nhập 0).`,
    H: `${product} lưu tại đơn vị; thống kê thực tế kỳ 01/10/2025–30/9/2026; Thủ trưởng đơn vị xác nhận`,
    I: `Phiếu khảo sát, đo thời gian thực tế thực hiện "${product}" kỳ 01/10/2025–30/9/2026; Thủ trưởng đơn vị xác nhận`,
  };
}
